// Parse backend multipart/form-data payload according to AI_PROGRAM_AUTOFILL_N8N_CONTRACT
const item = $input.first();
const body = item.json.body || item.json || {};
const runId = String(body.run_id || '');
const runType = String(body.type || 'program_autofill');

let parsedInput = {};
if (typeof body.input === 'string' && body.input.trim()) {
  try {
    parsedInput = JSON.parse(body.input);
  } catch (err) {
    throw new Error(`Invalid JSON in 'input' field: ${err.message}`);
  }
} else if (typeof body.input === 'object' && body.input !== null) {
  parsedInput = body.input;
}

const pastedText = typeof parsedInput.text === 'string' ? parsedInput.text : '';
const orderedFilenames = Array.isArray(parsedInput.files) ? parsedInput.files : [];

// Collect binary attachments in positional order matching input.files[i]
const binaryObj = item.binary || {};
const binaryKeys = Object.keys(binaryObj).sort();
const filesPayload = [];

for (let i = 0; i < binaryKeys.length; i++) {
  const key = binaryKeys[i];
  const bin = binaryObj[key];
  if (!bin || !bin.data) continue;
  const positionalName = orderedFilenames[i] || bin.fileName || `attachment_${i + 1}`;
  filesPayload.push({
    filename: positionalName,
    mime_type: bin.mimeType || 'application/octet-stream',
    content_base64: bin.data
  });
}

return [{
  json: {
    runpod_payload: {
      input: {
        run_id: runId,
        type: runType,
        input: JSON.stringify({ text: pastedText, files: orderedFilenames }),
        text: pastedText,
        files: filesPayload
      }
    }
  }
}];

// Transform RunPod output and enforce 2xx JSON object contract or throw HTTP error
const resp = $input.first().json;

if (resp.status === 'FAILED' || (resp.output && resp.output.error)) {
  const errMsg = (resp.output && resp.output.error) || resp.error || 'RunPod execution failed';
  throw new Error(`Extraction failed: ${errMsg}`);
}

const out = resp.output || resp;
if (!out || typeof out !== 'object' || Array.isArray(out)) {
  throw new Error('RunPod did not return a valid JSON object');
}

return [{ json: out }];
